import Foundation

/// The bundled life tables, decoded once and looked up by country.
///
/// **One file, one source per country.** `lifeTables.json` is generated by
/// `scripts/build-life-tables.py` from the publishing agency's own spreadsheet, and every table in it
/// names the agency, the edition and the year, because a life expectancy without a citation is a
/// number with no owner. The app adds countries by regenerating that file, never by typing numbers in
/// here.
///
/// It is `Data` and not `Domain` because it touches `Bundle.module`; the type it produces —
/// `LifeTable` — is pure.
public struct LifeTableStore: Sendable {

    /// What the resource holds, keyed by ISO 3166-1 alpha-3.
    private let tables: [String: [String: LifeTable]]

    /// The bundle's own name. Stated rather than built from a resource path because `Bundle.module`
    /// resolves it and a typo here is a crash at first read rather than a wrong number.
    private static let resourceName = "lifeTables"

    public init(tables: [String: [String: LifeTable]]) {
        self.tables = tables
    }

    /// Decodes the bundled resource, or returns an empty store.
    ///
    /// An empty store is the honest answer for a missing or malformed resource: the card that consumes
    /// it draws "no life table for this country" rather than failing to draw at all.
    public init() {
        guard
            let url = Bundle.module.url(forResource: Self.resourceName, withExtension: "json"),
            let data = try? Data(contentsOf: url)
        else {
            self = LifeTableStore(tables: [:])
            return
        }
        self.init(jsonData: data)
    }

    /// Decodes a JSON document of the resource's shape. The suite hands it the file from the source
    /// tree, which is the same bytes SwiftPM bundles — `Bundle.module` is not resolvable from the
    /// hand-linked test binary.
    public init(jsonData: Data) {
        guard let document = try? JSONDecoder().decode(Document.self, from: jsonData) else {
            self = LifeTableStore(tables: [:])
            return
        }
        self.tables = document.tables.mapValues { entry in
            entry.sexes.mapValues { series in
                LifeTable(
                    source: entry.source,
                    year: entry.year,
                    qx: series.qx,
                    ex: series.ex)
            }
        }
    }

    /// The table for a country and a sex key (`total`, `male`, `female`), falling back to `total` when
    /// the table has no split for that sex — which is what the reference's own tables do for anyone
    /// whose sex is not recorded.
    public func table(for countryCode: String, sex: String) -> LifeTable? {
        guard let entry = tables[countryCode.uppercased()] else { return nil }
        return entry[sex] ?? entry["total"]
    }

    /// Whether any table is bundled for this country — the fact the card states when it is false.
    public func hasTable(for countryCode: String) -> Bool {
        tables[countryCode.uppercased()] != nil
    }

    /// The country codes the bundle covers, sorted — a test reads this to assert the resource is not
    /// empty.
    public var countryCodes: [String] { tables.keys.sorted() }

    /// The resource's shape. `retrieved` is decoded so a stale bundle is visible in the file itself.
    private struct Document: Decodable {
        struct Entry: Decodable {
            struct Series: Decodable {
                let qx: [Double]
                let ex: [Double]
            }
            let source: String
            let year: Int
            let sexes: [String: Series]
        }
        let retrieved: String
        let tables: [String: Entry]
    }
}
